#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
A2A Mesh: Telepítő-artefakt ellenőrzés a futó gépen + izoláció-váltásnál minden OLVASÓ felkutatása

This module implements three key lessons from the Marveen feed:
1. Artifact presence in repo != installed on running machine. Verify on the live host.
2. On isolation/config switch, discover ALL readers (watchdog may still read old path).
3. Same symptom can have multiple independent causes — fix one, symptom may persist.

Run from the a2a_mesh repo root:
    python3 tools/artifact_runtime_check.py --check
    python3 tools/artifact_runtime_check.py --migrate
    python3 tools/artifact_runtime_check.py --switch-isolation /new/path
"""

import os
import sys
import json
import time
import shutil
import hashlib
import logging
import argparse
import subprocess
import re
from pathlib import Path
from dataclasses import dataclass, field, asdict
from typing import Optional

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
)
log = logging.getLogger("artifact_runtime_check")

REPO_ROOT = Path(__file__).resolve().parent.parent
ARTIFACT_REGISTRY_PATH = REPO_ROOT / "config" / "artifact_registry.json"
RUNTIME_STATE_PATH = Path("/var/lib/a2a_mesh/artifact_state.json")
READER_REGISTRY_PATH = REPO_ROOT / "config" / "reader_registry.json"


# ---------------------------------------------------------------------------
# Data structures
# ---------------------------------------------------------------------------

@dataclass
class ArtifactSpec:
    """Describes an artifact that should be installed on a running node."""
    name: str
    kind: str  # "systemd_unit", "keepalive_probe", "config_file", "binary", "ssh_host_key"
    repo_path: str  # path in the repo (template/source)
    install_path: str  # expected path on the running machine
    install_method: str  # "copy", "symlink", "systemd_install", "ssh_keygen"
    checksum_expected: Optional[str] = None  # sha256 of expected content
    post_install_cmd: Optional[str] = None  # command to run after install
    systemd_enable: bool = False  # if kind == systemd_unit, enable+start

    @classmethod
    def from_dict(cls, d: dict) -> "ArtifactSpec":
        return cls(**{k: d[k] for k in cls.__dataclass_fields__ if k in d})


@dataclass
class ArtifactCheckResult:
    name: str
    installed: bool
    checksum_match: bool
    detail: str
    needs_migration: bool = False


@dataclass
class ReaderInfo:
    """Describes a process/component that reads from a config/isolation path."""
    name: str
    pid: Optional[int]
    config_path: str  # path it's currently reading from
    reader_type: str  # "watchdog", "keepalive_loop", "sshd", "systemd_unit", "haos_container"
    open_files: list = field(default_factory=list)


