def load_artifact_registry() -> list[ArtifactSpec]:
    """Load artifact registry from config file, or use defaults."""
    if ARTIFACT_REGISTRY_PATH.exists():
        with open(ARTIFACT_REGISTRY_PATH) as f:
            data = json.load(f)
        return [ArtifactSpec.from_dict(d) for d in data.get("artifacts", [])]
    return [ArtifactSpec.from_dict(d) for d in DEFAULT_ARTIFACTS]


def ensure_registry_file():
    """Create the registry config file from defaults if it doesn't exist."""
    if not ARTIFACT_REGISTRY_PATH.exists():
        ARTIFACT_REGISTRY_PATH.parent.mkdir(parents=True, exist_ok=True)
        with open(ARTIFACT_REGISTRY_PATH, "w") as f:
            json.dump({"artifacts": DEFAULT_ARTIFACTS}, f, indent=2)
        log.info(f"Created artifact registry at {ARTIFACT_REGISTRY_PATH}")


# ---------------------------------------------------------------------------
# Checksum utilities
# ---------------------------------------------------------------------------

def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


# ---------------------------------------------------------------------------
# Artifact verification on the running machine
# ---------------------------------------------------------------------------

class ArtifactVerifier:
    """
    Verifies that artifacts are actually installed on the running machine,
    not just present in the repo. This addresses lesson (1): repo presence
    does not imply installation.
    """

    def __init__(self, artifacts: list[ArtifactSpec]):
        self.artifacts = artifacts
        self.results: list[ArtifactCheckResult] = []

    def check_all(self) -> list[ArtifactCheckResult]:
        self.results = []
        for spec in self.artifacts:
            result = self._check_one(spec)
            self.results.append(result)
            status = "OK" if result.installed else "MISSING"
            log.info(f"  [{status}] {spec.name} -> {spec.install_path}: {result.detail}")
        return self.results

    def _check_one(self, spec: ArtifactSpec) -> ArtifactCheckResult:
        install_path = Path(spec.install_path)

        # Check if file exists on running machine
        if not install_path.exists():
            return ArtifactCheckResult(
                name=spec.name,
                installed=False,
                checksum_match=False,
                detail=f"Not found at {install_path}",
                needs_migration=True,
            )

        # For systemd units, check if enabled
        if spec.kind == "systemd_unit":
            return self._check_systemd(spec, install_path)

        # For config files and binaries, compare checksum with repo template
        checksum_match = True
        if spec.repo_path:
            repo_file = REPO_ROOT / spec.repo_path
            if repo_file.exists():
                installed_hash = sha256_file(install_path)
                repo_hash = sha256_file(repo_file)
                checksum_match = (installed_hash == repo_hash)
                if not checksum_match:
                    return ArtifactCheckResult(
                        name=spec.name,
                        installed=True,
                        checksum_match=False,
                        detail=f"Installed but outdated (installed={installed_hash[:12]}, repo={repo_hash[:12]})",
                        needs_migration=True,
                    )

        # Check executable bit for scripts
        if spec.kind == "keepalive_probe":
            if not os.access(install_path, os.X_OK):
                return ArtifactCheckResult(
                    name=spec.name,
                    installed=True,
                    checksum_match=checksum_match,
                    detail="Installed but not executable",
                    needs_migration=True,
                )

        return ArtifactCheckResult(
            name=spec.name,
            installed=True,
            checksum_match=True,
            detail="Installed and up-to-date",
        )

    def _check_systemd(self, spec: ArtifactSpec, install_path: Path) -> ArtifactCheckResult:
        """Check if a systemd unit is installed and optionally enabled."""
        unit_name = install_path.name

        # Check if unit is loaded by systemd
        try:
            result = subprocess.run(
                ["systemctl", "is-enabled", unit_name],
                capture_output=True, text=True, timeout=5
            )
            enabled = result.returncode == 0 and "enabled" in result.stdout.strip()
        except (FileNotFoundError, subprocess.TimeoutExpired):
            # systemd not available (e.g., in container) — just check file presence
            enabled = False

        # Check if running
        try:
            result = subprocess.run(
                ["systemctl", "is-active", unit_name],
                capture_output=True, text=True, timeout=5
            )
            active = "active" in result.stdout.strip()
        except (FileNotFoundError, subprocess.TimeoutExpired):
            active = False

        # Compare content with repo template
        repo_file = REPO_ROOT / spec.repo_path if spec.repo_path else None
        checksum_match = True
        if repo_file and repo_file.exists():
            installed_hash = sha256_file(install_path)
            repo_hash = sha256_file(repo_file)
            checksum_match = (installed_hash == repo_hash)

        if not checksum_match:
            return ArtifactCheckResult(
                name=spec.name,
                installed=True,
                checksum_match=False,
                detail=f"Unit file present but outdated (enabled={enabled}, active={active})",
                needs_migration=True,
            )

        if spec.systemd_enable and not enabled:
            return ArtifactCheckResult(
                name=spec.name,
                installed=True,
                checksum_match=True,
                detail=f"Unit file OK but not enabled (active={active})",
                needs_migration=True,
            )

        return ArtifactCheckResult(
            name=spec.name,
            installed=True,
            checksum_match=True,
            detail=f"Unit installed (enabled={enabled}, active={active})",
        )

    def summary(self) -> dict:
        total = len(self.results)
        installed = sum(1 for r in self.results if r.installed)
        up_to_date = sum(1 for r in self.results if r.installed and r.checksum_match)
        needs_migration = sum(1 for r in self.results if r.needs_migration)
        return {
            "total": total,
            "installed": installed,
            "up_to_date": up_to_date,
            "needs_migration": needs_migration,
            "all_ok": needs_migration == 0,
        }


# ---------------------------------------------------------------------------
# Reader Discovery — find ALL readers when isolation/config switches
# ---------------------------------------------------------------------------

class ReaderDiscovery:
    """
    Discovers all processes/components reading from a given config/isolation path.
    This addresses lesson (2): on isolation switch, watchdog may still read
    from the old path, reading an empty directory.
    """

    # Known reader types and how to find them
    READER_PATTERNS = {
        "watchdog": [
            r"a2a.watchdog",
            r"watchdog.*a2a",
        ],
        "keepalive_loop": [
            r"a2a.keepalive",
            r"keepalive_probe",
        ],
        "sshd": [
            r"sshd.*-f\s+(\S+)",
        ],
        "haos_container": [
            r"docker.*a2a",
            r"containerd.*a2a",
        ],
    }

    def __init__(self):
        self.readers: list[ReaderInfo] = []

    def discover_all_readers(self, config_path: str) -> list[ReaderInfo]:
        """
        Find all processes that are reading from or referencing the given
        config/isolation path. Uses /proc scanning for open files and
        command-line inspection.
        """
        self.readers = []
        config_path_resolved = str(Path(config_path).resolve())

        # Method 1: Scan /proc for processes with open files in the config path
        self._scan_proc_open_files(config_path_resolved)

        # Method 2: Scan /proc for processes with config path in cmdline
        self._scan_proc_cmdline(config_path_resolved)

        # Method 3: Check systemd units that reference the path
        self._scan_systemd_units(config_path_resolved)

        # Method 4: Check for HAOS containers mounting the path
        self._scan_containers(config_path_resolved)

        # Deduplicate by pid
        seen_pids = set()
        unique = []
        for r in self.readers:
            key = (r.pid, r.config_path)
            if key not in seen_pids:
                seen_pids.add(key)
                unique.append(r)
        self.readers = unique

        return self.readers

    def _scan_proc_open_files(self, config_path: str):
        """Scan /proc/*/fd/ for open file descriptors pointing into config path."""
        proc = Path("/proc")
        if not proc.exists():
            return

        for pid_dir in proc.iterdir():
            if not pid_dir.name.isdigit():
                continue
            pid = int(pid_dir.name)
            fd_dir = pid_dir / "fd"
            if not fd_dir.exists():
                continue
            try:
                for fd_link in fd_dir.iterdir():
                    try:
                        target = fd_link.resolve()
                        target_str = str(target)
                        if config_path in target_str or str(Path(config_path).parent) in target_str:
                            cmdline = self._read_cmdline(pid)
                            reader_type = self._classify_reader(cmdline)
                            self.readers.append(ReaderInfo(
                                name=self._process_name(pid),
                                pid=pid,
                                config_path=target_str,
                                reader_type=reader_type,
                                open_files=[target_str],
                            ))
                    except (OSError, PermissionError):
                        continue
            except (OSError, PermissionError):
                continue

    def _scan_proc_cmdline(self, config_path: str):
        """Scan /proc/*/cmdline for references to the config path."""
        proc = Path("/proc")
        if not proc.exists():
            return

        for pid_dir in proc.iterdir():
            if not pid_dir.name.isdigit():
                continue
            pid = int(pid_dir.name)
            cmdline = self._read_cmdline(pid)
            if not cmdline:
                continue
            if config_path in cmdline or str(Path(config_path).parent) in cmdline:
                reader_type = self._classify_reader(cmdline)
                # Avoid duplicates from open file scan
                already = any(r.pid == pid for r in self.readers)
                if not already:
                    self.readers.append(ReaderInfo(
                        name=self._process_name(pid),
                        pid=pid,
                        config_path=config_path,
                        reader_type=reader_type,
                        open_files=[],
                    ))

    def _scan_systemd_units(self, config_path: str):
        """Check systemd units for references to the config path."""
        try:
            result = subprocess.run(
                ["systemctl", "list-units", "--type=service", "--all", "--no-legend", "--plain"],
                capture_output=True, text=True, timeout=10
            )
            if result.returncode != 0:
                return
            for line in result.stdout.strip().split("\n"):
                parts = line.split()
                if not parts:
                    continue
                unit_name = parts[0]
                if "a2a" not in unit_name:
                    continue
                # Check unit file for config path reference
                try:
                    show_result = subprocess.run(
                        ["systemctl", "cat", unit_name],
                        capture_output=True, text=True, timeout=5
                    )
                    if config_path in show_result.stdout or str(Path(config_path).parent) in show_result.stdout:
                        self.readers.append(ReaderInfo(
                            name=unit_name,
                            pid=None,
                            config_path=config_path,
                            reader_type="systemd_unit",
                            open_files=[],
                        ))
                except (subprocess.TimeoutExpired, FileNotFoundError):
                    continue
        except (FileNotFoundError, subprocess.TimeoutExpired):
            return

    def _scan_containers(self, config_path: str):
        """Check for Docker/HAOS containers that mount the config path."""
        try:
            result = subprocess.run(
                ["docker", "ps", "--format", "{{.Names}}\t{{.ID}}"],
                capture_output=True, text=True, timeout=10
            )
            if result.returncode != 0:
                return
            for line in result.stdout.strip().split("\n"):
                if not line.strip():
                    continue
                parts = line.split("\t")
                if len(parts) < 2:
                    continue
                name, container_id = parts[0], parts[1]
                if "a2a" not in name.lower() and "mesh" not in name.lower():
                    continue
                # Check mounts
                inspect_result = subprocess.run(
                    ["docker", "inspect", "--format", "{{json .Mounts}}", container_id],
                    capture_output=True, text=True, timeout=5
                )
                if inspect_result.returncode == 0:
                    try:
                        mounts = json.loads(inspect_result.stdout.strip())
                        for mount in mounts:
                            src = mount.get("Source", "")
                            if config_path in src or str(Path(config_path).parent) in src:
                                self.readers.append(ReaderInfo(
                                    name=f"container:{name}",
                                    pid=None,
                                    config_path=src,
                                    reader_type="haos_container",
                                    open_files=[],
                                ))
                    except json.JSONDecodeError:
                        continue
        except (FileNotFoundError, subprocess.TimeoutExpired):
            return

    def _read_cmdline(self, pid: int) -> str:
        try:
            with open(f"/proc/{pid}/cmdline", "rb") as f:
                return f.read().replace(b"\x00", b" ").decode("utf-8", errors="replace").strip()
        except (OSError, PermissionError):
            return ""

    def _process_name(self, pid: int) -> str:
        try:
            with open(f"/proc/{pid}/comm", "r") as f:
                return f.read().strip()
        except (OSError, PermissionError):
            return f"pid:{pid}"

    def _classify_reader(self, cmdline: str) -> str:
        for reader_type, patterns in self.READER_PATTERNS.items():
            for pattern in patterns:
                if re.search(pattern, cmdline, re.IGNORECASE):
                    return reader_type
        return "unknown"

    def report(self) -> dict:
        by_type = {}
        for r in self.readers:
            by_type.setdefault(r.reader_type, []).append(asdict(r))
        return {
            "total_readers": len(self.readers),
            "by_type": {k: len(v) for k, v in by_type.items()},
            "readers": [asdict(r) for r in self.readers],
        }


# ---------------------------------------------------------------------------
# Updater/Migration — handles existing nodes that need artifact updates
# ---------------------------------------------------------------------------

class UpdaterMigration:
    """
    Migrates existing nodes by installing/updating artifacts on the running
    machine. This addresses lesson (1): template modifications only reach
    new installations; existing machines need separate migration.
    """

    def __init__(self, artifacts: list[ArtifactSpec]):
        self.artifacts = artifacts
        self.verifier = ArtifactVerifier(artifacts)
        self.migrated: list[str] = []
        self.failed: list[str] = []

    def run_migration(self, dry_run: bool = False) -> dict:
        """Check all artifacts and migrate those that need it."""
        log.info("=== Artifact Verification Phase ===")
        results = self.verifier.check_all()
        summary = self.verifier.summary()
        log.info(f"Summary: {summary}")

        if summary["all_ok"]:
            log.info("All artifacts are installed and up-to-date. No migration needed.")
            return {"migrated": [], "failed": [], "summary": summary, "dry_run": dry_run}

        needs_migration = [r for r in results if r.needs_migration]
        log.info(f"\n=== Migration Phase ({len(needs_migration)} artifacts need update) ===")

        if dry_run:
            log.info("[DRY RUN] Would migrate:")
            for r in needs_migration:
                log.info(f"  - {r.name}: {r.detail}")
            return {
                "migrated": [],
                "failed": [],
                "would_migrate": [r.name for r in needs_migration],
                "summary": summary,
                "dry_run": True,
            }

        for result in needs_migration:
            spec = next((a for a in self.artifacts if a.name == result.name), None)
            if not spec:
                continue
            try:
                self._migrate_one(spec)
                self.migrated.append(spec.name)
            except Exception as e:
                log.error(f"Failed to migrate {spec.name}: {e}")
                self.failed.append(spec.name)

        # Re-verify after migration
        log.info("\n=== Post-Migration Verification ===")
        self.verifier.check_all()
        post_summary = self.verifier.summary()
        log.info(f"Post-migration summary: {post_summary}")

        return {
            "migrated": self.migrated,
            "failed": self.failed,
            "summary": summary,
            "post_summary": post_summary,
            "dry_run": False,
        }

    def _migrate_one(self, spec: ArtifactSpec):
        """Install or update a single artifact on the running machine."""
        log.info(f"Migrating: {spec.name}")

        install_path = Path(spec.install_path)
        install_path.parent.mkdir(parents=True, exist_ok=True)

        if spec.install_method == "copy":
            self._migrate_copy(spec, install_path)
        elif spec.install_method == "symlink":
            self._migrate_symlink(spec, install_path)
        elif spec.install_method == "systemd_install":
            self._migrate_systemd(spec, install_path)
        elif spec.install_method == "ssh_keygen":
            self._migrate_ssh_key(spec, install_path)
        else:
            raise ValueError(f"Unknown install method: {spec.install_method}")

        # Run post-install command
        if spec.post_install_cmd:
            log.info(f"  Running post-install: {spec.post_install_cmd}")
            result = subprocess.run(
                spec.post_install_cmd, shell=True, capture_output=True, text=True, timeout=30
            )
            if result.returncode != 0:
                log.warning(f"  Post-install command failed: {result.stderr}")

        # Save state
        self._save_state(spec)

    def _migrate_copy(self, spec: ArtifactSpec, install_path: Path):
        repo_file = REPO_ROOT / spec.repo_path
        if not repo_file.exists():
            raise FileNotFoundError(f"Repo source not found: {repo_file}")
        # Backup existing if present
        if install_path.exists():
            backup = install_path.with_suffix(install_path.suffix + ".bak")
            shutil.copy2(install_path, backup)
            log.info(f"  Backed up existing to {backup}")
        shutil.copy2(repo_file, install_path)
        log.info(f"  Copied {repo_file} -> {install_path}")

    def _migrate_symlink(self, spec: ArtifactSpec, install_path: Path):
        repo_file = REPO_ROOT / spec.repo_path
        if not repo_file.exists():
            raise FileNotFoundError(f"Repo source not found: {repo_file}")
        if install_path.is_symlink() or install_path.exists():
            install_path.unlink()
        install_path.symlink_to(repo_file.resolve())
        log.info(f"  Symlinked {install_path} -> {repo_file}")

    def _migrate_systemd(self, spec: ArtifactSpec, install_path: Path):
        # Copy unit file
        self._migrate_copy(spec, install_path)

        # Reload systemd daemon
        try:
            subprocess.run(["systemctl", "daemon-reload"], check=True, timeout=10)
            log.info("  systemctl daemon-reload completed")
        except (FileNotFoundError, subprocess.TimeoutExpired, subprocess.CalledProcessError):
            log.warning("  systemctl daemon-reload failed (systemd may not be available)")

        # Enable and start if required
        if spec.systemd_enable:
            unit_name = install_path.name
            try:
                subprocess.run(["systemctl", "enable", unit_name], check=True, timeout=10)
                log.info(f"  Enabled {unit_name}")
                subprocess.run(["systemctl", "restart", unit_name], check=True, timeout=15)
                log.info(f"  Restarted {unit_name}")
            except (FileNotFoundError, subprocess.TimeoutExpired, subprocess.CalledProcessError) as e:
                log.warning(f"  Could not enable/restart {unit_name}: {e}")

    def _migrate_ssh_key(self, spec: ArtifactSpec, install_path: Path):
        if install_path.exists():
            log.info(f"  SSH key already exists at {install_path}, skipping")
            return
        try:
            subprocess.run(
                ["ssh-keygen", "-t", "ed25519", "-f", str(install_path), "-N", "", "-q"],
                check=True, timeout=15
            )
            log.info(f"  Generated SSH host key at {install_path}")
        except (FileNotFoundError, subprocess.CalledProcessError, subprocess.TimeoutExpired) as e:
            log.warning(f"  Could not generate SSH key: {e}")

    def _save_state(self, spec: ArtifactSpec):
        RUNTIME_STATE_PATH.parent.mkdir(parents=True, exist_ok=True)
        state = {}
        if RUNTIME_STATE_PATH.exists():
            try:
                with open(RUNTIME_STATE_PATH) as f:
                    state = json.load(f)
            except (json.JSONDecodeError, OSError):
                state = {}
        state[spec.name] = {
            "install_path": spec.install_path,
            "migrated_at": time.strftime("%Y-%m-%dT%H:%M:%S"),
            "checksum": sha256_file(Path(spec.install_path)) if Path(spec.install_path).exists() else None,
        }
        with open(RUNTIME_STATE_PATH, "w") as f:
            json.dump(state, f, indent=2)


# ---------------------------------------------------------------------------
# Isolation Switch — coordinate reader discovery + artifact re-check
# ---------------------------------------------------------------------------

class IsolationSwitch:
    """
    Handles config/isolation path switches. This addresses lesson (2):
    when switching isolation, ALL readers must be discovered and notified/restarted,
    because watchdog may still read from the old path (empty directory).

    Also addresses lesson (3): same symptom (e.g., empty reads) can come from
    multiple independent causes — we check both path correctness AND reader
    liveness after the switch.
    """

    def __init__(self, artifacts: list[ArtifactSpec]):
        self.artifacts = artifacts
        self.discovery = ReaderDiscovery()

    def switch(self, old_path: str, new_path: str, dry_run: bool = False) -> dict:
        log.info(f"=== Isolation Switch: {old_path} -> {new_path} ===")

        # Phase 1: Discover all readers of the OLD path
        log.info(f"\nPhase 1: Discovering all readers of old path: {old_path}")
        old_readers = self.discovery.discover_all_readers(old_path)
        log.info(f"  Found {len(old_readers)} readers on old path:")
        for r in old_readers:
            log.info(f"    - {r.name} (pid={r.pid}, type={r.reader_type}, path={r.config_path})")

        # Phase 2: Discover all readers of the NEW path (if it exists)
        log.info(f"\nPhase 2: Discovering all readers of new path: {new_path}")
        new_readers = self.discovery.discover_all_readers(new_path)
        log.info(f"  Found {len(new_readers)} readers on new path:")
        for r in new_readers:
            log.info(f"    - {r.name} (pid={r.pid}, type={r.reader_type}, path={r.config_path})")

        # Phase 3: Identify stale readers (reading old path, not new)
        stale_readers = []
        old_pids = {r.pid for r in old_readers if r.pid is not None}
        new_pids = {r.pid for r in new_readers if r.pid is not None}
        stale_pids = old_pids - new_pids
        stale_readers = [r for r in old_readers if r.pid in stale_pids]

        log.info(f"\nPhase 3: Stale readers (on old path, not on new): {len(stale_readers)}")
        for r in stale_readers:
            log.warning(f"  STALE: {r.name} (pid={r.pid}) still reading from {r.config_path}")

        if dry_run:
            log.info("\n[DRY RUN] Would restart/reload these stale readers")
            return {
                "old_path": old_path,
                "new_path": new_path,
                "old_readers": [asdict(r) for r in old_readers],
                "new_readers": [asdict(r) for r in new_readers],
                "stale_readers": [asdict(r) for r in stale_readers],
                "actions_taken": [],
                "dry_run": True,
            }

        # Phase 4: Restart/reload stale readers
        actions_taken = []
        for r in stale_readers:
            action = self._restart_reader(r, new_path)
            actions_taken.append(action)

        # Phase 5: Verify — re-discover readers on new path
        log.info("\nPhase 5: Post-switch verification — re-discovering readers on new path")
        time.sleep(2)  # Give processes time to restart
        post_readers = self.discovery.discover_all_readers(new_path)
        post_pids = {r.pid for r in post_readers if r.pid is not None}
        still_stale = [r for r in stale_readers if r.pid and r.pid not in post_pids]

        # Phase 6: Multi-cause symptom check (lesson 3)
        # The symptom "empty reads" could be caused by:
        #   (a) reader still on old path (stale)
        #   (b) new path directory is empty
        #   (c) reader crashed during restart
        # We check all three independently.
        log.info("\nPhase 6: Multi-cause symptom check")
        causes = self._check_multiple_causes(new_path, post_readers, still_stale)

        return {
            "old_path": old_path,
            "new_path": new_path,
            "old_readers": [asdict(r) for r in old_readers],
            "new_readers": [asdict(r) for r in new_readers],
            "stale_readers": [asdict(r) for r in stale_readers],
            "actions_taken": actions_taken,
            "post_switch_readers": [asdict(r) for r in post_readers],
            "still_stale": [asdict(r) for r in still_stale],
            "symptom_causes": causes,
            "dry_run": False,
        }

    def _restart_reader(self, reader: ReaderInfo, new_path: str) -> dict:
        """Attempt to restart/reload a reader so it picks up the new path."""
        action = {"reader": reader.name, "pid": reader.pid, "type": reader.reader_type, "action": "none", "success": False}

        if reader.reader_type == "systemd_unit":
            try:
                subprocess.run(["systemctl", "restart", reader.name], check=True, timeout=15)
                action["action"] = "systemctl restart"
                action["success"] = True
                log.info(f"  Restarted systemd unit: {reader.name}")
            except Exception as e:
                action["action"] = "systemctl restart (failed)"
                action["error"] = str(e)
                log.error(f"  Failed to restart {reader.name}: {e}")

        elif reader.pid is not None:
            try:
                # Send SIGHUP for graceful reload
                os.kill(reader.pid, 1)  # SIGHUP
                action["action"] = "SIGHUP"
                action["success"] = True
                log.info(f"  Sent SIGHUP to {reader.name} (pid={reader.pid})")
            except ProcessLookupError:
                action["action"] = "SIGHUP (process gone)"
                action["success"] = True
                log.info(f"  Process {reader.pid} already gone")
            except PermissionError as e:
                action["action"] = "SIGHUP (permission denied)"
                action["error"] = str(e)
                log.error(f"  Cannot signal {reader.pid}: {e}")

        return action

    def _check_multiple_causes(self, new_path: str, readers: list[ReaderInfo], still_stale: list[ReaderInfo]) -> list[dict]:
        """
        Check for multiple independent causes of the "empty reads" symptom.
        Lesson (3): same symptom can have multiple causes; fixing one may not fix the symptom.
        """
        causes = []

        # Cause A: Stale readers still on old path
        if still_stale:
            causes.append({
                "cause": "stale_readers_on_old_path",
                "severity": "high",
                "detail": f"{len(still_stale)} readers still reading from old path",
                "readers": [r.name for r in still_stale],
            })

        # Cause B: New path directory is empty or doesn't exist
        new_path_obj = Path(new_path)
        if not new_path_obj.exists():
            causes.append({
                "cause": "new_path_does_not_exist",
                "severity": "critical",
                "detail": f"New path {new_path} does not exist",
            })
        elif new_path_obj.is_dir():
            contents = list(new_path_obj.iterdir())
            if not contents:
                causes.append({
                    "cause": "new_path_empty_directory",
                    "severity": "high",
                    "detail": f"New path {new_path} is an empty directory",
                })

        # Cause C: No readers found on new path at all
        if not readers:
            causes.append({
                "cause": "no_readers_on_new_path",
                "severity": "high",
                "detail": "No readers discovered on the new path after switch",
            })

        # Cause D: Readers exist but process is not running (zombie config)
        for r in readers:
            if r.pid is not None:
                try:
                    os.kill(r.pid, 0)  # Check if process exists
                except ProcessLookupError:
                    causes.append({
                        "cause": "reader_process_dead",
                        "severity": "medium",
                        "detail": f"Reader {r.name} (pid={r.pid}) is not running",
                    })
                except PermissionError:
                    pass  # Process exists but we can't signal it

        if not causes:
            causes.append({
                "cause": "none",
                "severity": "info",
                "detail": "No issues detected after isolation switch",
            })

        for c in causes:
            log.info(f"  Cause check: [{c['severity']}] {c['cause']}: {c['detail']}")

        return causes


